import {Utils} from "./Utils.js";

/**
 * Representation of a channel.
 *
 * Events emitted:
 * <ul>
 *   <li><code>subscribed</code>, when a ServerSession has subscribed to this channel</li>
 *   <li><code>message</code>, when a message arrives on this channel</li>
 *   <li><code>unsubscribed</code>, when a ServerSession has unsubscribed from this channel</li>
 * </ul>
 *
 * @param {CometDServer} cometd the CometD server object
 * @param {string} name the channel name
 * @returns {ServerChannel} a ServerChannel object
 * @constructor
 */
export class ServerChannel {
    #cometd;
    #name;
    #wildNames = [];
    #listeners = {};
    #subscribers = {};

    constructor(cometd, name) {
        this.#cometd = cometd;

        if (!name || name.charAt(0) !== "/" || name === "/") {
            throw new Error("invalid channel " + name);
        }
        this.#name = name;

        const segments = name.split("/");
        const lastSegment = segments[segments.length - 1];
        if (lastSegment !== "*" && lastSegment !== "**") {
            let c = "/";
            for (let i = segments.length - 1; i > 0; --i) {
                this.#wildNames.unshift(c + "**");
                if (i > 1) {
                    c += segments[segments.length - i] + "/";
                }
            }
            this.#wildNames.unshift(c + "*");
        }
    }

    /**
     * @returns {string} the channel name
     */
    get name() {
        return this.#name;
    }

    /**
     * @returns {boolean} whether this channel is a meta channel
     */
    get meta() {
        return /^\/meta\//.test(this.name);
    }

    /**
     * @returns {boolean} whether this channel is a service channel
     */
    get service() {
        return /^\/service\//.test(this.name);
    }

    /**
     * @returns {boolean} whether this channel is a broadcast channel
     */
    get broadcast() {
        return !this.meta && !this.service;
    }

    /**
     * @returns {string[]} the list of parent wild channels
     */
    get wildNames() {
        return this.#wildNames;
    }

    /**
     * Publishes a message to all subscribers.
     *
     * @param {ServerSession} [sender] the session that sends the message
     * @param {*} data the message data
     * @param {boolCallbackFn} [callback] the callback notified when the publish completes
     */
    publish(sender, data, callback) {
        callback = callback || this.#noop;
        this.#cometd._publish(this, sender, {
            channel: this.name,
            data: data
        }, false, callback);
    }

    /**
     * @param event the event type
     * @returns {function[]} the listeners for the given event
     */
    listeners(event) {
        return this.#listeners[event] || [];
    }

    /**
     * Adds a listener function for the given event.
     *
     * @param {string} event the event type
     * @param {function} fn the listener function
     */
    addListener(event, fn) {
        return Utils.addListener(this.#listeners, event, fn);
    }

    /**
     * Removes a listener function for the given event.
     *
     * @param {string} event the event type
     * @param {function} fn the listener function
     */
    removeListener(event, fn) {
        return Utils.removeListener(this.#listeners, event, fn);
    }

    /**
     * @returns {ServerSession[]} the list of ServerSession subscribed to this channel
     */
    get subscribers() {
        const result = [];
        for (let id in this.#subscribers) {
            if (this.#subscribers.hasOwnProperty(id)) {
                result.push(this.#subscribers[id]);
            }
        }
        return result;
    }

    // PRIVATE APIs.

    _subscribe(session, message, callback) {
        if (!session._handshaken || this.meta) {
            callback(undefined, false);
        } else {
            if (this.broadcast) {
                const existing = this.#subscribers[session.id];
                if (!existing) {
                    this.#subscribers[session.id] = session;
                    session._subscribed(this);
                    Utils.notifyEvent(this.listeners("subscribed"), [this, session, message]);
                    Utils.notifyEvent(this.#cometd.listeners("subscribed"), [this, session, message]);
                }
            }
            callback(undefined, true);
        }
    }

    _unsubscribe(session, message, callback) {
        const existing = this.#subscribers[session.id];
        if (existing) {
            delete this.#subscribers[session.id];
            session._unsubscribed(this);
            Utils.notifyEvent(this.listeners("unsubscribed"), [this, session, message]);
            Utils.notifyEvent(this.#cometd.listeners("unsubscribed"), [this, session, message]);
        }
        callback(undefined, true);
    }

    _sweep() {
        if (this.meta) {
            return;
        }
        for (let id in this.#subscribers) {
            if (this.#subscribers.hasOwnProperty(id)) {
                return;
            }
        }
        for (let event in this.#listeners) {
            if (this.#listeners.hasOwnProperty(event)) {
                return;
            }
        }
        this.#cometd._removeServerChannel(this);
    }

    #noop() {
    }
}
